pub fn compute_spec_CASE_16_monitor_health_decision_guarantee(
  In_monitor_mode_state: Isolette_Thermostat_Rust::ThermostatMode,
  monitor_mode_state: Isolette_Thermostat_Rust::ThermostatMode,
  api_diagnostic_facts: Isolette_Thermostat_Rust::MonitorDiagnosticFacts,
  api_interface_facts: Isolette_Thermostat_Rust::MonitorInterfaceFacts) -> bool
{
  (implies!(
    !(api_diagnostic_facts.power_epoch_changed) & !(api_interface_facts.interface_failure) &
      !(api_diagnostic_facts.internal_failure_latched) &
      api_interface_facts.current_valid &
      (In_monitor_mode_state == Isolette_Thermostat_Rust::ThermostatMode::INIT),
    (monitor_mode_state == Isolette_Thermostat_Rust::ThermostatMode::NORMAL))) &
    (implies!(
      !(api_diagnostic_facts.power_epoch_changed) & !(api_interface_facts.interface_failure) &
        !(api_diagnostic_facts.internal_failure_latched) &
        api_interface_facts.current_valid &
        (In_monitor_mode_state == Isolette_Thermostat_Rust::ThermostatMode::NORMAL),
      (monitor_mode_state == Isolette_Thermostat_Rust::ThermostatMode::NORMAL)))
}

/** Compute Entrypoint Contract
  *
  * guarantee CASE_17_monitor_mode_transition
  * @param In_monitor_mode_state pre-state state variable
  * @param monitor_mode_state post-state state variable
  * @param api_diagnostic_facts incoming data port
  * @param api_interface_facts incoming data port
  * @param api_mode_for_alarm outgoing data port
  * @param api_mode_for_interface outgoing data port
  */
pub fn compute_spec_CASE_17_monitor_mode_transition_guarantee(
  In_monitor_mode_state: Isolette_Thermostat_Rust::ThermostatMode,
  monitor_mode_state: Isolette_Thermostat_Rust::ThermostatMode,
  api_diagnostic_facts: Isolette_Thermostat_Rust::MonitorDiagnosticFacts,
  api_interface_facts: Isolette_Thermostat_Rust::MonitorInterfaceFacts,
  api_mode_for_alarm: Isolette_Thermostat_Rust::ThermostatMode,
  api_mode_for_interface: Isolette_Thermostat_Rust::ThermostatMode) -> bool
{
  (implies!(
    api_diagnostic_facts.power_epoch_changed,
    (monitor_mode_state == Isolette_Thermostat_Rust::ThermostatMode::INIT))) &
    (implies!(
      !(api_diagnostic_facts.power_epoch_changed) &
        (In_monitor_mode_state == Isolette_Thermostat_Rust::ThermostatMode::FAILED),
      (monitor_mode_state == Isolette_Thermostat_Rust::ThermostatMode::FAILED))) &
    (implies!(
      !(api_diagnostic_facts.power_epoch_changed) &
        (In_monitor_mode_state == Isolette_Thermostat_Rust::ThermostatMode::INIT) &
        (api_interface_facts.interface_failure | api_diagnostic_facts.internal_failure_latched |
          !(api_interface_facts.current_valid)) &
        api_diagnostic_facts.init_timeout_expired,
      (monitor_mode_state == Isolette_Thermostat_Rust::ThermostatMode::FAILED))) &
    (implies!(
      !(api_diagnostic_facts.power_epoch_changed) &
        (In_monitor_mode_state == Isolette_Thermostat_Rust::ThermostatMode::INIT) &
        (api_interface_facts.interface_failure | api_diagnostic_facts.internal_failure_latched |
          !(api_interface_facts.current_valid)) &
        !(api_diagnostic_facts.init_timeout_expired),
      (monitor_mode_state == Isolette_Thermostat_Rust::ThermostatMode::INIT))) &
    (implies!(
      !(api_diagnostic_facts.power_epoch_changed) &
        (In_monitor_mode_state == Isolette_Thermostat_Rust::ThermostatMode::NORMAL) &
        (api_interface_facts.interface_failure | api_diagnostic_facts.internal_failure_latched |
          !(api_interface_facts.current_valid)),
      (monitor_mode_state == Isolette_Thermostat_Rust::ThermostatMode::FAILED))) &
    (api_mode_for_interface == monitor_mode_state) &
    (api_mode_for_alarm == monitor_mode_state)
}

